 19	type ActiveDrag = {
 20	  pointerId: number;
 21	  startPoint: Point;
 22	  latestPoint: Point;
 23	  grabOffset: PhysicalPoint;
 24	  startedAt: number;
 25	  isDragging: boolean;
 26	  needsMove: boolean;
 27	  moveTask: Promise<void> | null;
 28	};
 29	
 30	export class FloatingBallDragController {
 31	  private active: ActiveDrag | null = null;
 32	
 33	  constructor(
 34	    private readonly host: FloatingBallDragHost,
 35	    private readonly thresholdPx = 4,
 36	    private readonly clickMaxMs = 280,
 37	  ) {}
 38	
 39	  get isDragging(): boolean {
 40	    return this.active?.isDragging ?? false;
 41	  }
 42	
 43	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean {
 44	    if (this.active) return false;
 45	    this.active = {
 46	      pointerId,
 47	      startPoint: point,
 48	      latestPoint: point,
 49	      grabOffset,
 50	      startedAt,
 51	      isDragging: false,
 52	      needsMove: false,
 53	      moveTask: null,
 54	    };
 55	    return true;
 56	  }
 57	
 58	  move(pointerId: number, point: Point): boolean {
 59	    const drag = this.active;
 60	    if (!drag || drag.pointerId !== pointerId) return false;
 61	    drag.latestPoint = point;
 62	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) {
 63	      this.start(drag);
 64	      return true;
 65	    }
 66	    if (drag.isDragging) this.queueMove(drag);
 67	    return false;
 68	  }
 69	
 70	  finish(
 71	    pointerId: number,
 72	    point: Point,
 73	    allowClick: boolean,
 74	    now: number,
 75	  ): FloatingBallDragOutcome | null {
 76	    const drag = this.active;
 77	    if (!drag || drag.pointerId !== pointerId) return null;
 78	
 79	    drag.latestPoint = point;
 80	    this.active = null;
 81	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
 82	    if (!drag.isDragging) {
 83	      return {
 84	        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
 85	        completion: null,
 86	      };
 87	    }
 88	
 89	    this.queueMove(drag);
 90	    return { kind: "drag", completion: this.persistAfterFinalMove(drag) };
 91	  }
 92	
 93	  private movedBeyondThreshold(drag: ActiveDrag): boolean {
 94	    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
 95	      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
 96	  }
 97	
 98	  private start(drag: ActiveDrag): void {
 99	    drag.isDragging = true;
100	    this.queueMove(drag);
101	  }
102	
103	  private queueMove(drag: ActiveDrag): void {
104	    drag.needsMove = true;
105	    if (drag.moveTask) return;
106	
107	    const task = this.moveToLatestCursorPosition(drag);
108	    drag.moveTask = task;
109	    void task.then(
110	      () => { if (drag.moveTask === task) drag.moveTask = null; },
111	      () => { if (drag.moveTask === task) drag.moveTask = null; },
112	    );
113	  }
114	
115	  private async moveToLatestCursorPosition(drag: ActiveDrag): Promise<void> {
116	    while (drag.needsMove) {
117	      drag.needsMove = false;
118	      const cursor = await this.host.cursorPosition();
119	      await this.host.setPosition({
120	        x: cursor.x - drag.grabOffset.x,
121	        y: cursor.y - drag.grabOffset.y,
122	      });
123	    }
124	  }
125	
126	  private async persistAfterFinalMove(drag: ActiveDrag): Promise<void> {
127	    const finalMove = drag.moveTask;
128	    if (finalMove) await finalMove;
129	    await this.host.persistPosition();
130	  }
131	}
