 70	  finish(
 71	    pointerId: number,
 72	    point: Point,
 73	    allowClick: boolean,
 74	    now: number,
 75	  ): FloatingBallDragOutcome | null {
 76	    const drag = this.active;
 77	    if (!drag || drag.pointerId !== pointerId) return null;
 78	
 79	    drag.latestPoint = point;
 80	    this.active = null;
 81	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
 82	    if (!drag.isDragging) {
 83	      return {
 84	        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
 85	        completion: null,
 86	      };
 87	    }
 88	
 89	    this.queueMove(drag);
 90	    return { kind: "drag", completion: this.persistAfterFinalMove(drag) };
 91	  }
