 93	  private movedBeyondThreshold(drag: ActiveDrag): boolean {
 94	    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
 95	      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
 96	  }
