103	  private queueMove(drag: ActiveDrag): void {
104	    drag.needsMove = true;
105	    if (drag.moveTask) return;
106	
107	    const task = this.moveToLatestCursorPosition(drag);
108	    drag.moveTask = task;
109	    void task.then(
110	      () => { if (drag.moveTask === task) drag.moveTask = null; },
111	      () => { if (drag.moveTask === task) drag.moveTask = null; },
112	    );
113	  }
